def clothing_full_lines(n=2500, seed=77):
    R = random.Random(seed); out = []
    kinds = [("casual",22),("patterned",8),("layered",10),("suit",9),("smart",6),("uniform",8),("athletic",5),("outdoor",4),("work",5),("traditional",5),("vintage",3),("cosplay",5),("near",5),("formal_evening",1.5),("street",5)]
    def shoe(): return R.choice(SHOES)
    for _ in range(n):
        k = R.choices([x[0] for x in kinds], weights=[x[1] for x in kinds], k=1)[0]; acc = R.choice(ACC); tag = R.choice(TAGS)
        if k == "casual": s = f"{R.choice(FITS)}__outfit_color__ __outfit_casual_top__ with __outfit_color__ __outfit_casual_bottom__, {shoe()}, {acc}, {tag}"
        elif k == "patterned": s = f"__outfit_pattern__ __outfit_casual_top__ with __outfit_material__ __outfit_casual_bottom__, {shoe()}, {tag}"
        elif k == "layered": s = f"__outfit_color__ __outfit_outerwear__ over a __outfit_color__ __outfit_casual_top__ and __outfit_casual_bottom__, {shoe()}, {acc}, {tag}"
        elif k == "suit": s = f"__outfit_color__ __outfit_suit_style__ with {R.choice(SHIRT)} and {R.choice(TIE)}, polished {R.choice(['oxford shoes','derby shoes','loafers','dress boots'])}, formal business attire"
        elif k == "smart": s = f"smart casual __outfit_color__ blazer over a __outfit_color__ __outfit_casual_top__ with chinos and {shoe()}, {acc}, modern smart casual"
        elif k == "uniform": s = f"__outfit_color__ __outfit_uniform_type__, {acc}, {R.choice(['neat and tidy look','professional appearance','highly detailed outfit','worn and practical look'])}"
        elif k == "athletic": s = f"{R.choice(['fitted','loose','moisture-wicking','vintage'])} __outfit_color__ {R.choice(['training tee','gym tank','running shirt','compression top','basketball jersey','football jersey'])} with {R.choice(['training shorts','joggers','compression tights','track pants','baggy shorts'])}, {R.choice(['running shoes','training shoes','high-top sneakers'])}, athletic wear"
        elif k == "outdoor": s = f"{R.choice(['a waterproof shell jacket','a heavy fleece','a puffer vest','a canvas work jacket','a wool plaid jacket'])} in __outfit_color__ over a {R.choice(['thermal shirt','flannel shirt','merino base layer'])} with {R.choice(['hiking pants','cargo pants','rugged jeans'])}, {R.choice(['hiking boots','work boots','insulated boots'])}, {R.choice(['a beanie','a trucker cap','a wide-brim hat','a neck gaiter'])}, rugged outdoorsy look"
        elif k == "work": s = f"{R.choice(['a canvas apron','a hi-vis vest','a denim work shirt','coveralls','a leather tool belt','a welder jacket','a butcher apron','a carpenter apron'])} in __outfit_color__ over a {R.choice(['work shirt','tee','thermal top'])} and {R.choice(['work pants','heavy jeans','cargo pants'])}, {R.choice(['steel-toe boots','work boots'])}, practical work clothes"
        elif k == "traditional": s = R.choice(TRAD)
        elif k == "vintage": s = R.choice(VINT)
        elif k == "cosplay": s = "__outfit_cosplay__"
        elif k == "near": s = R.choices([a for a, _ in NEAR], weights=[b for _, b in NEAR], k=1)[0]
        elif k == "formal_evening": s = f"a classic black tuxedo with a {R.choice(['bow tie','silk tie'])}, white dress shirt, cufflinks and polished patent shoes, black-tie formal wear"
        else: s = f"{R.choice(['baggy','oversized','boxy'])} __outfit_color__ {R.choice(['hoodie','graphic tee','varsity jacket','track jacket','puffer jacket'])} with {R.choice(['baggy jeans','cargo pants','track pants'])}, {R.choice(['chunky sneakers','high-top sneakers','skate shoes'])}, {R.choice(['a beanie','a bucket hat','a snapback cap'])}, urban streetwear"
        out.append(s)
    return out
